// Groups containers by app (Docker Compose project) and finds broken parts of apps that are running.
// An app that is completely stopped is treated as switched off on purpose: no alarm.
const IGNORE_APPS = $('Settings').first().json.ignore_apps || [];   // apps that should never be watched
const apps = {};
for (const item of $input.all()) {
  const c = item.json;
  const app = (c.Labels || {})['com.docker.compose.project'];
  if (!app || IGNORE_APPS.includes(app)) continue;
  (apps[app] = apps[app] || []).push(c);
}
// How long a running container has been up, from Docker's status text ("Up 31 seconds", "Up About a minute", ...).
// Lower bound, so a start time estimated from it is never too early.
const upSeconds = status => {
  const m = /^Up (Less than a second|About an? (minute|hour)|(\d+) (second|minute|hour|day|week)s?)/.exec(status || '');
  if (!m) return null;
  if (m[1] === 'Less than a second') return 0;
  if (m[2]) return m[2] === 'minute' ? 60 : 3600;
  return Number(m[3]) * { second: 1, minute: 60, hour: 3600, day: 86400, week: 604800 }[m[4]];
};
const problems = [];
for (const [app, containers] of Object.entries(apps)) {
  const appIsUp = containers.some(c => c.State === 'running' || c.State === 'restarting');
  if (!appIsUp) continue;
  for (const c of containers) {
    const name = c.Names[0].replace(/^\//, '');
    let kind = null;
    if (c.State === 'restarting') kind = 'crash_loop';
    else if (c.State === 'exited' || c.State === 'dead') kind = 'stopped';
    if (!kind) continue;
    problems.push({ json: {
      app, container: name, id: c.Id, kind, state: c.State, status: c.Status,
      service: (c.Labels || {})['com.docker.compose.service'] || name,
      app_containers: containers.map(x => ({ name: x.Names[0].replace(/^\//, ''), service: (x.Labels || {})['com.docker.compose.service'], state: x.State, status: x.Status, up_seconds: upSeconds(x.Status),
        depends_on: ((x.Labels || {})['com.docker.compose.depends_on'] || '').split(',').map(s => s.split(':')[0]).filter(Boolean) })),
    }});
  }
}
return problems;

// Turns the Docker details of one broken container into plain facts.
const p = $('Find problems').item.json;
const d = $json;
const st = d.State || {};
const TZ = $('Settings').first().json.timezone || 'UTC';
const when = t => (t && !t.startsWith('0001')) ? new Date(t).toISOString() : null;
const show = t => t ? new Date(t).toLocaleString('de-DE', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'unknown time';
const facts = {
  app: p.app,
  container: p.container,
  service: p.service,
  kind: p.kind,
  state: st.Status,
  exit_code: st.ExitCode,
  oom_killed: !!st.OOMKilled,
  restart_count: d.RestartCount || 0,
  restart_policy: (d.HostConfig && d.HostConfig.RestartPolicy && d.HostConfig.RestartPolicy.Name) || 'no',
  last_started: when(st.StartedAt),
  last_stopped: when(st.FinishedAt),
  docker_error: st.Error || null,
  memory_limit_mb: d.HostConfig && d.HostConfig.Memory ? Math.round(d.HostConfig.Memory / 1048576) : null,
  app_containers: p.app_containers,
};
// What Docker itself tells us about how the container ended.
let how;
if (facts.oom_killed) how = 'The system killed it because it ran out of memory (OOMKilled).';
else if (facts.kind === 'crash_loop') how = `It crashes right after starting (exit code ${facts.exit_code}) and Docker keeps restarting it: ${facts.restart_count} restarts so far.`;
else if (facts.exit_code === 0) how = `It stopped cleanly (exit code 0) at ${show(facts.last_stopped)}. That is a normal shutdown, not a crash.`;
else if (facts.exit_code === 137) how = `It was killed (exit code 137) at ${show(facts.last_stopped)}.`;
else how = `It stopped with an error (exit code ${facts.exit_code}) at ${show(facts.last_stopped)}.`;
facts.how_it_ended = how;
return { json: facts };

// Reads the last 200 log lines of the broken container and pulls out what matters:
// the error messages (grouped, with how often and when), the stack trace and the code location.
const f = $('Facts').item.json;
const raw = typeof $json.data === 'string' ? $json.data : '';

// Docker puts 8 bytes of framing before each line; the timestamp marks where the real text starts.
const TS = /(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z) ?(.*)$/;
const lines = [];
for (const piece of raw.split('\n')) {
  const m = piece.match(TS);
  if (m) lines.push({ t: m[1], text: m[2].replace(/\x1b\[[0-9;]*m/g, '').trimEnd() });
}

const ERROR = /(error|exception|fatal|panic|traceback|failed|refused|denied|cannot|can't|could not|unhandled|timed? ?out|ECONNREFUSED|EADDRINUSE|ENOENT|EACCES|out of memory|killed|no space left)/i;
const STACK = /^\s*(at .+:\d+(:\d+)?\)?$|File ".+", line \d+|\S+\.(java|kt|go|rb|py|ts|js|php):\d+)/;
const key = s => s.replace(/0x[0-9a-f]+/gi, '#').replace(/\d+/g, '#').slice(0, 200);

const groups = {};
lines.forEach((l, i) => {
  if (!ERROR.test(l.text) || STACK.test(l.text)) return;
  const k = key(l.text);
  const g = groups[k] || (groups[k] = { message: l.text.slice(0, 300), count: 0, first_seen: l.t, last_seen: l.t, stack: [] });
  g.count++;
  g.last_seen = l.t;
  if (!g.stack.length) {
    for (let j = i + 1; j < Math.min(i + 20, lines.length); j++) {
      if (STACK.test(lines[j].text)) g.stack.push(lines[j].text.trim());
      else if (g.stack.length) break;
    }
  }
});
const errors = Object.values(groups).sort((a, b) => b.count - a.count).slice(0, 5);

// The first stack frame that points into the app's own code, not into libraries.
const code_location = errors.flatMap(e => e.stack)
  .find(s => !/node_modules|site-packages|node:internal|internal\/|<anonymous>/.test(s)) || null;

return { json: { ...f, log_lines_read: lines.length, errors, code_location, last_lines: lines.slice(-15).map(l => l.text) } };

// Connects the facts of all broken containers into root causes.
// Every cause comes from evidence Docker or the logs gave us. Nothing here is guessed.
const items = $input.all().map(i => i.json);
const byApp = {};
for (const f of items) (byApp[f.app] = byApp[f.app] || []).push(f);

// Known error messages and what they mean. First match wins.
const PATTERNS = [
  { re: /no space left on device|ENOSPC/i, type: 'disk_full', cause: 'The disk is full, so the app cannot write.', step: 'Free disk space (`df -h`, `docker system df`), then restart the container.' },
  { re: /EADDRINUSE|address already in use|bind: address/i, type: 'port_in_use', cause: 'The port the app wants is already used by another process.', step: 'Find what holds the port (`ss -ltnp`) and stop it, or change the app port.' },
  { re: /password authentication failed|access denied for user|authentication failed/i, type: 'bad_credentials', cause: 'The app is using a wrong password or user for a service it connects to.', step: 'Compare the credentials in the app configuration (.env) with the service.' },
  { re: /(environment variable|env var).*(missing|not set|required|undefined)|missing required (env|config)|is not defined in (the )?env/i, type: 'missing_config', cause: 'A required setting (environment variable) is missing.', step: 'Add the missing variable to the app configuration and restart.' },
  { re: /permission denied|EACCES/i, type: 'permission', cause: 'The app is not allowed to read or write a file or port it needs.', step: 'Check file owners and permissions of the mounted folders.' },
  { re: /ENOENT|no such file or directory|cannot find module|module not found|ModuleNotFoundError/i, type: 'missing_file', cause: 'A file or module the app needs does not exist in the container.', step: 'Check the build (was the file copied into the image?) and the paths in the configuration.' },
];

let TZ = 'UTC';
try { TZ = $('Settings').first().json.timezone || 'UTC'; } catch (e) {}
const fmtTime = t => t ? new Date(t).toLocaleString('de-DE', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : 'unknown time';
const seen = e => `${e.count} times in the last 200 log lines, last at ${fmtTime(e.last_seen)}`;
const incidents = [];

for (const [app, broken] of Object.entries(byApp)) {
  const all = broken[0].app_containers;
  const svc = name => all.find(c => c.service === name || c.name === name);
  const isDown = c => c && c.state !== 'running';
  const factsOf = c => broken.find(b => b.container === c.name);
  const explained = new Set();   // containers whose problem is caused by another container
  const recovering = new Set();  // containers whose last errors are older than the fix of what they needed
  const rootOf = {};             // container -> root container

  // Rule 1: a container fails because something it depends on is down.
  // Evidence: compose depends_on, or the logs name the service (e.g. "db:5432").
  for (const f of broken) {
    const me = svc(f.service);
    const named = new Set(me.depends_on);
    const text = f.errors.map(e => e.message).join('\n');
    for (const c of all) if (c.service && c.service !== f.service && new RegExp(`\\b${c.service}(:\\d+)?\\b`).test(text)) named.add(c.service);
    const dep = [...named].map(svc).find(isDown);
    if (dep) { explained.add(f.container); rootOf[f.container] = dep.name; continue; }
    // Recovering: the part it complains about is running again, and every error is older than that restart.
    // The container is only waiting for Docker's next restart, so this is not a new problem.
    const backAt = [...named].map(svc).filter(c => c && c.state === 'running' && c.up_seconds != null).map(c => Date.now() - c.up_seconds * 1000);
    const lastErr = f.errors.map(e => Date.parse(e.last_seen)).sort().pop();
    if (f.kind === 'crash_loop' && backAt.length && lastErr && lastErr < Math.min(...backAt)) recovering.add(f.container);
  }
  // Follow chains: frontend -> backend -> db gives root db.
  const root = n => rootOf[n] ? root(rootOf[n]) : n;

  const roots = [...new Set(broken.filter(f => !recovering.has(f.container)).map(f => root(f.container)))];
  for (const r of roots) {
    const f = factsOf({ name: r });
    const victims = broken.filter(b => b.container !== r && root(b.container) === r);
    // Running containers that depend (directly or through others) on a broken one are affected too.
    const down = new Set([r, ...victims.map(v => v.container)]);
    let grew = true;
    while (grew) { grew = false; for (const c of all) if (!down.has(c.name) && c.depends_on.some(s => down.has(svc(s) && svc(s).name))) { down.add(c.name); grew = true; } }
    const affected = [...down].filter(n => n !== r);

    const inc = { app, root_container: r, service: f ? f.service : r, affected, evidence: [], next_steps: [], cause_type: null, cause: null, code_location: null, needs_investigation: false, fingerprint: null };
    const ev = s => inc.evidence.push(s);
    for (const v of victims) {
      const top = v.errors[0];
      ev(`${v.container}: ${v.how_it_ended}`);
      if (top) ev(`${v.container} log: "${top.message.slice(0, 160)}" (${seen(top)})`);
    }
    if (f) ev(`${r}: ${f.how_it_ended}`);
    const top = f && f.errors[0];
    const pattern = f && PATTERNS.find(p => f.errors.some(e => p.re.test(e.message)));

    if (f && f.oom_killed) {
      inc.cause_type = 'out_of_memory';
      inc.cause = `${r} was killed by the system because it ran out of memory${f.memory_limit_mb ? ` (limit ${f.memory_limit_mb} MB)` : ''}.`;
      inc.next_steps.push('Check the memory use of the app (`docker stats`) for a leak, then raise the memory limit if the use is normal.');
    } else if (pattern) {
      const e = f.errors.find(e => pattern.re.test(e.message));
      ev(`${r} log: "${e.message.slice(0, 160)}" (${seen(e)})`);
      inc.cause_type = pattern.type; inc.cause = `${r}: ${pattern.cause}`; inc.next_steps.push(pattern.step);
    } else if (f && f.code_location && top) {
      inc.cause_type = 'code_error'; inc.code_location = f.code_location;
      inc.cause = `A bug in the app code: "${top.message.slice(0, 160)}" at ${f.code_location.replace(/^at /, '')}.`;
      ev(`${r} log: "${top.message.slice(0, 160)}" (${seen(top)})`); ev(`Stack trace points to ${f.code_location}`);
      inc.next_steps.push(`Open ${f.code_location.replace(/^at /, '')} and fix the error; the full stack trace is in the container logs.`);
    } else if (f && f.kind === 'stopped' && f.exit_code === 0) {
      inc.cause_type = 'stopped_by_command';
      const manual = f.restart_policy === 'unless-stopped' || f.restart_policy === 'always';
      inc.cause = `${r} is not running. It did not crash: it shut down cleanly (exit code 0) at ${fmtTime(f.last_stopped)}` +
        (manual ? `, which happens after a stop command (\`docker stop\` or \`docker compose stop\`). Docker never restarts a container that was stopped this way.` : '.');
      // Only a shutdown line from the minutes before the stop counts as evidence for this stop.
      const stopAt = Date.parse(f.last_stopped);
      const shutdownLine = f.errors.find(e => /administrator command|shutting down|received (SIGTERM|signal)|graceful/i.test(e.message)
        && Math.abs(stopAt - Date.parse(e.last_seen)) < 10 * 60 * 1000);
      if (shutdownLine) ev(`${r} log: "${shutdownLine.message.slice(0, 160)}"`);
      inc.next_steps.push(`Start it again: \`docker compose -p ${app} start ${inc.service}\``);
      inc.next_steps.push(`Find out who stopped it on ${fmtTime(f.last_stopped).slice(0, 10)} so it does not happen again.`);
    } else if (f && top) {
      inc.cause_type = 'app_error';
      inc.cause = `${r} ${f.kind === 'crash_loop' ? 'crashes on start' : 'stopped'} with this error: "${top.message.slice(0, 200)}".`;
      ev(`${r} log: "${top.message.slice(0, 160)}" (${seen(top)})`);
      inc.next_steps.push(`Read the full log around ${fmtTime(top.last_seen)}: \`docker logs --since 10m ${r}\``);
      inc.needs_investigation = true;   // the message is known, but not why it happens
    } else {
      inc.cause_type = 'unknown';
      inc.cause = `${r} ${f ? f.how_it_ended : 'is down'} The logs contain no error message.`;
      inc.needs_investigation = true;
    }
    // Since when: the stop time of a stopped root, or the first error we still have in the logs.
    const firstErr = [f, ...victims].filter(Boolean).flatMap(x => x.errors).map(e => e.first_seen).sort()[0];
    if (f && f.kind === 'stopped' && f.last_stopped) { inc.down_since = f.last_stopped; inc.down_since_exact = true; }
    else { inc.down_since = firstErr || null; inc.down_since_exact = false; }
    inc.affected_detail = affected.map(n => {
      const v = victims.find(x => x.container === n);
      if (v) return `${n}: ${v.kind === 'crash_loop' ? 'crash loop' : 'stopped'}, because it needs ${r}`;
      const c = all.find(x => x.name === n);
      const dep = c.depends_on.map(svc).find(x => x && down.has(x.name));
      return `${n}: still running, but it depends on ${dep ? dep.name : r}, which is down, so its users get errors`;
    });
    inc.victim_services = victims.map(v => v.service);
    if (victims.length) inc.next_steps.push(`After that, ${victims.map(v => v.container).join(', ')} should recover by itself; check it with \`docker ps\`.`);
    inc.title = `${app}: ${inc.cause_type === 'stopped_by_command' ? `${inc.service} is stopped` : inc.cause_type.replace(/_/g, ' ')}` + (affected.length ? `, ${affected.length} other part(s) affected` : '');
    // Same root, same kind of cause = same incident, so repeats are counted instead of new tickets.
    inc.fingerprint = `${app}|${r}|${inc.cause_type}`;
    incidents.push({ json: inc });
  }
}
return incidents;

// The question for the AI: what we already know, and what is still open.
const i = $json;
const text = [
  `App: ${i.app}`,
  `Broken container: ${i.root_container}`,
  `What the rules found: ${i.cause}`,
  `Facts so far:`, ...i.evidence.map(e => `- ${e}`),
  i.affected.length ? `Other parts affected: ${i.affected.join(', ')}` : '',
  '',
  'Find the root cause. The error above may only be a symptom. Check the other containers of this app, their logs and states, and the server metrics.',
].filter(Boolean).join('\n');
return { json: { ...i, question: text } };

// Keeps only evidence the AI really saw. Every quote must appear in a tool result.
const inc = $('Investigation brief').item.json;
const steps = $json.intermediateSteps || [];
const seen = steps.map(s => String(s.observation || '')).join('\n').toLowerCase();
const norm = s => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
let ans = {};
try { ans = JSON.parse(String($json.output).replace(/<think>[\s\S]*?<\/think>/g, '').match(/\{[\s\S]*\}/)[0]); } catch (e) { ans = {}; }
const quotes = (ans.evidence || []).map(String);
const verified = quotes.filter(q => q.length > 5 && seen.replace(/\s+/g, ' ').includes(norm(q).replace(/^"|"$/g, '')));
const rejected = quotes.filter(q => !verified.includes(q));
const tools_used = steps.map(s => `${s.action && s.action.tool}(${JSON.stringify((s.action && s.action.toolInput) || {})})`);
const out = { ...inc, investigation: { tools_used, checked: ans.checked || [], rejected_evidence: rejected } };
delete out.question;
if (ans.cause && verified.length) {
  out.cause_type = 'found_by_investigation';
  out.cause = ans.cause;
  if (ans.root_container) out.investigation_root = ans.root_container;
  out.evidence = [...inc.evidence, ...verified.map(q => `found by investigation: "${q.slice(0, 200)}"`)];
  out.next_steps = (ans.next_steps || []).slice(0, 3);
  out.needs_investigation = false;
} else {
  out.cause = `${inc.cause} The investigation could not back up a deeper cause with evidence.`;
  out.next_steps = [...inc.next_steps, ...(ans.checked && ans.checked.length ? [`Already checked: ${ans.checked.join('; ')}`] : [])];
}
return { json: out };

// Settings for this installation. install.sh replaces this block with the values from .env.
return [{ json: {
  email_from: 'you@example.com',
  email_to: 'you@example.com',
  ai_investigation: 'off',
  timezone: 'Europe/Berlin',
  app_labels: {},
  ignore_apps: ['ai-ops-assistant'],
} }];

parameters.query:
SELECT
  (SELECT id FROM incidents WHERE fingerprint = $1 AND status = 'open' ORDER BY id DESC LIMIT 1) AS open_id,
  (SELECT emailed_at IS NOT NULL FROM incidents WHERE fingerprint = $1 AND status = 'open' ORDER BY id DESC LIMIT 1) AS emailed;

parameters.jsCode:
// New problem: save it and email it. Known problem whose email went out: only count it.
// Known problem whose email failed last time: try the email again.
return $input.all().map((it, i) => {
  const inc = $('Find cause').itemMatching(i).json;
  const open_id = it.json.open_id || null;
  const action = !open_id ? 'new' : (it.json.emailed ? 'repeat' : 'notify');
  return { json: { ...inc, open_id, action }, pairedItem: { item: i } };
});

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Text between backticks is a command: shown as code so it can be copied.
const fmt = s => esc(s).replace(/`([^`]+)`/g, '<code style="background:#f2f2f2;padding:1px 4px;border-radius:3px">$1</code>');
const list = (xs, ordered) => xs && xs.length ? `<${ordered ? 'ol' : 'ul'}>${xs.map(x => `<li style="margin:3px 0">${fmt(x)}</li>`).join('')}</${ordered ? 'ol' : 'ul'}>` : '<p>none</p>';
const S = $('Settings').first().json;
const TZ = S.timezone || 'UTC';
const local = t => new Date(t).toLocaleString('de-DE', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const label = app => (S.app_labels || {})[app] || app;
const duration = ms => { const m = Math.max(1, Math.round(ms / 60000)); if (m < 60) return `${m} minute${m > 1 ? 's' : ''}`;
  const h = Math.floor(m / 60); if (h < 48) return `${h} hour${h > 1 ? 's' : ''}`; const dd = Math.floor(h / 24); return `${dd} days`; };
const tlist = (xs, ordered) => (xs || []).map((x, k) => `  ${ordered ? (k + 1) + '.' : '-'} ${x}`).join('\n') || '  none';
const section = (h, body) => `<h3 style="margin:18px 0 6px;font-size:15px">${h}</h3>${body}`;
const page = (title, color, inner) => `<div style="font-family:Arial,sans-serif;max-width:720px;color:#222"><div style="border-left:5px solid ${color};padding:4px 12px;margin-bottom:8px"><h2 style="margin:0;font-size:18px">${esc(title)}</h2></div>${inner}<p style="color:#888;font-size:12px;margin-top:24px">Sent by ai-ops-assistant. It only reads containers, logs and metrics; it changed nothing on the server.</p></div>`;

// The first email for a new incident: cause, evidence and next steps from the rules.
const inc = $('Decide').item.json;
const id = $json.id;
const waiting = inc.needs_investigation && $('Settings').first().json.ai_investigation !== 'off';
// Subject: what is broken, for how long, and what it breaks.
const svcName = inc.service;
const headline = inc.cause_type === 'stopped_by_command' ? `${svcName} stopped` : `${svcName}: ${(inc.cause_type || 'problem').replace(/_/g, ' ')}`;
const since = inc.down_since ? duration(Date.now() - Date.parse(inc.down_since)) : null;
const victims = (inc.victim_services || []);
const subject = `[ai-ops] #${id} ${label(inc.app)}: ${headline}${since ? (inc.down_since_exact ? ` for ${since}` : ` (at least ${since})`) : ''}${victims.length ? `, ${victims.join(' and ')} crashing` : ''}`;
const sinceLine = inc.down_since ? `${inc.down_since_exact ? 'Down' : 'Failing'} for ${inc.down_since_exact ? '' : 'at least '}${since}, since ${local(inc.down_since)}.` : '';
const html = page(subject, '#c0392b',
  (sinceLine ? `<p style="font-size:15px;margin:6px 0 0"><b>${esc(sinceLine)}</b></p>` : '') +
  section('Cause', `<p>${fmt(inc.cause)}</p>`) +
  (inc.code_location ? section('Where in the code', `<p><code>${esc(inc.code_location)}</code></p>`) : '') +
  section('Affected', (inc.affected_detail || inc.affected).length ? list(inc.affected_detail || inc.affected) : '<p>only this container</p>') +
  section('Evidence', list(inc.evidence)) +
  section('Next steps', list(inc.next_steps, true)) +
  (waiting ? section('Investigation', '<p>The rules found the error but not why it happens. An AI investigation is running now; its result follows in a second email.</p>') : ''));
const text = [subject, '', sinceLine, '', 'Cause:', '  ' + inc.cause, inc.code_location ? `Where in the code:\n  ${inc.code_location}` : '',
  'Affected:', tlist((inc.affected_detail || inc.affected).length ? (inc.affected_detail || inc.affected) : ['only this container']), 'Evidence:', tlist(inc.evidence), 'Next steps:', tlist(inc.next_steps, true),
  waiting ? '\nAn AI investigation is running now; its result follows in a second email.' : ''].filter(Boolean).join('\n');
return { json: { ...inc, incident_id: id, subject, html, text } };

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
