const fmt = s => esc(s).replace(/`([^`]+)`/g, '<code style="background:#f2f2f2;padding:1px 4px;border-radius:3px">$1</code>');
const list = (xs, ordered) => xs && xs.length ? `<${ordered ? 'ol' : 'ul'}>${xs.map(x => `<li style="margin:3px 0">${fmt(x)}</li>`).join('')}</${ordered ? 'ol' : 'ul'}>` : '<p>none</p>';
const S = $('Settings').first().json;
const TZ = S.timezone || 'UTC';
const local = t => new Date(t).toLocaleString('de-DE', { timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
const label = app => (S.app_labels || {})[app] || app;
const duration = ms => { const m = Math.max(1, Math.round(ms / 60000)); if (m < 60) return `${m} minute${m > 1 ? 's' : ''}`;
  const h = Math.floor(m / 60); if (h < 48) return `${h} hour${h > 1 ? 's' : ''}`; const dd = Math.floor(h / 24); return `${dd} days`; };
const tlist = (xs, ordered) => (xs || []).map((x, k) => `  ${ordered ? (k + 1) + '.' : '-'} ${x}`).join('\n') || '  none';
const section = (h, body) => `<h3 style="margin:18px 0 6px;font-size:15px">${h}</h3>${body}`;
const page = (title, color, inner) => `<div style="font-family:Arial,sans-serif;max-width:720px;color:#222"><div style="border-left:5px solid ${color};padding:4px 12px;margin-bottom:8px"><h2 style="margin:0;font-size:18px">${esc(title)}</h2></div>${inner}<p style="color:#888;font-size:12px;margin-top:24px">Sent by ai-ops-assistant. It only reads containers, logs and metrics; it changed nothing on the server.</p></div>`;

// The second email: what the AI investigation found, with only the evidence it really saw.
const inc = $('Check evidence').item.json;
const inv = inc.investigation || {};
const found = inc.cause_type === 'found_by_investigation';
const subject = `[ai-ops] #${inc.incident_id} investigation: ${found ? 'root cause found' : 'no deeper cause found'}`;
const html = page(subject, found ? '#2c7be5' : '#888',
  section(found ? 'Root cause' : 'Result', `<p>${fmt(inc.cause)}</p>`) +
  (found ? section('Starts in', `<p><code>${esc(inc.investigation_root || inc.root_container)}</code></p>`) : '') +
  section('Evidence', list(inc.evidence)) +
  section('Next steps', list(inc.next_steps, true)) +
  section('How it was investigated', list(inv.tools_used && inv.tools_used.length ? inv.tools_used : ['the AI did not call any tool'])) +
  (inv.rejected_evidence && inv.rejected_evidence.length ? section('Thrown out', `<p>The AI claimed these, but they were not in any tool result, so they are not used:</p>${list(inv.rejected_evidence)}`) : ''));
const text = [subject, '', (found ? 'Root cause:' : 'Result:'), '  ' + inc.cause, 'Evidence:', tlist(inc.evidence), 'Next steps:', tlist(inc.next_steps, true),
  'How it was investigated:', tlist(inv.tools_used), inv.rejected_evidence && inv.rejected_evidence.length ? 'Thrown out (not in any tool result):\n' + tlist(inv.rejected_evidence) : ''].filter(Boolean).join('\n');
return { json: { ...inc, subject, html, text } };

// Closes open incidents whose containers are healthy again, or whose app was switched off.
const containers = $('List containers').all().map(i => i.json);
const nameOf = c => c.Names[0].replace(/^\//, '');
const state = n => { const c = containers.find(c => nameOf(c) === n); return c ? c.State : 'gone'; };
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r.id) continue;
  const appParts = containers.filter(c => (c.Labels || {})['com.docker.compose.project'] === r.app);
  const appOff = !appParts.some(c => c.State === 'running' || c.State === 'restarting');
  const parts = [r.root_container, ...(r.affected || [])];
  const healthy = state(r.root_container) === 'running' && parts.every(n => ['running', 'gone'].includes(state(n)));
  if (appOff) out.push({ json: { ...r, resolved_note: 'The whole app was switched off, so this incident is closed.' } });
  else if (healthy) out.push({ json: { ...r, resolved_note: `${r.root_container} is running again and every affected part is up.` } });
}
return out;

