// Short email when an incident is over.
const r = $json;
const mins = Math.max(1, Math.round((Date.parse(r.resolved_at) - Date.parse(r.first_seen)) / 60000));
const subject = `[ai-ops] resolved #${r.id} ${r.title}`;
const html = page(subject, '#27ae60', `<p>${esc(r.resolved_note)}</p><p>Open for ${mins} minute(s), seen in ${r.occurrences} scan(s).</p>` + section('Cause was', `<p>${esc(r.cause)}</p>`));
